#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY so the garbage collector keeps it alive; a raw pointer was
	// collected mid-game and dereferenced in OnGoalScored (crash, shipping log).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "ScoreTracker was a raw UArenaScoreTracker* not marked UPROPERTY(). Unreal's garbage collector only keeps UObjects alive via UPROPERTY/strong references (the Outer does not protect an object), so GC destroyed ScoreTracker mid-game. The shipping log shows \"LogGarbage: Collecting garbage: 412 objects purged\" at 21:05:13, then a goal at 21:05:27 called OnGoalScored -> UArenaScoreTracker::AddPoints, which dereferenced the dangling pointer and raised EXCEPTION_ACCESS_VIOLATION. Fix: declared it as UPROPERTY() TObjectPtr<UArenaScoreTracker> in ArenaGameMode.h so GC keeps it alive. It ran fine in the editor because the editor is less aggressive with GC and keeps more references.",
  "no_colors_cause": "The arena palette /Game/Data/Palettes/DA_Primary is loaded at runtime by string path via LoadObject, which is not a cook-time reference. With bCookAll=False and only /Game/Data/Effects listed in DirectoriesToAlwaysCook, the palette was never cooked into the pak file, so LoadObject failed at runtime (\"Couldn't find file for package /Game/Data/Palettes/DA_Primary\") and the HUD fell back to gray. Fix: added +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to Config/DefaultGame.ini so the palette is always cooked. It ran fine in the editor because the editor loads assets directly from disk rather than from the pak."
}
